   249	async function withBindingLock<T>(stateRoot: string, bindingId: string, mutation: () => Promise<T>): Promise<T> {
   250	  const lockPath = bindingLockPath(stateRoot, bindingId);
   251	  const deadline = Date.now() + LOCK_TIMEOUT_MS;
   252	  await mkdir(dirname(lockPath), { recursive: true, mode: 0o700 });
   253	
   254	  while (true) {
   255	    try {
   256	      await mkdir(lockPath, { mode: 0o700 });
   257	      break;
   258	    } catch (error) {
   259	      if (!isNodeError(error) || error.code !== "EEXIST") throw error;
   260	      if (Date.now() >= deadline) {
   261	        throw new WorkContextError(
   262	          "WORK_CONTEXT_AMBIGUOUS",
   263	          `Timed out acquiring the lock for Work Context binding ${bindingId}`,
   264	        );
   265	      }
   266	      await sleep(LOCK_RETRY_DELAY_MS);
   267	    }
   268	  }
   269	
   270	  try {
   271	    return await mutation();
   272	  } finally {
   273	    await rm(lockPath, { recursive: true, force: true });
   274	  }
   275	}
