   308	        throw new WorkContextError(
   309	          "WORK_CONTEXT_MISMATCH",
   310	          `Session ${options.host}/${options.sessionId} is already bound to a different collaboration space or lifecycle`,
   311	        );
   312	      }
   313	
   314	      const binding: WorkContextBinding = {
