   328	    const binding: WorkContextBinding = {
   329	      version: 1,
   330	      id: bindingId,
   331	      status: "active",
   332	      host: options.host,
   333	      session_id: options.sessionId,
   334	      bound_at: observedAt,
   335	      last_seen_at: observedAt,
   336	      expires_at: expiration,
   337	      collaboration_space: collaborationSpace,
   338	      provenance: {
   339	        kind: options.provenanceKind ?? "host_lifecycle",
   340	        lifecycle,
   341	        observed_cwd: observedCwd,
   342	      },
   343	    };
