   362	export async function supersedeWorkContextBinding(
   363	  options: SupersedeWorkContextBindingOptions,
   364	): Promise<WorkContextBinding> {
   365	  const bindingId = requireBindingId(options.bindingId);
   366	  const replacementBindingId = requireBindingId(options.replacementBindingId);
   367	  if (bindingId === replacementBindingId) {
   368	    throw new WorkContextError("WORK_CONTEXT_MISMATCH", "A Work Context binding cannot supersede itself");
   369	  }
   370	
   371	  const stateRoot = resolveWorkContextStateRoot(options.stateRoot);
   372	  const replacement = await requireWorkContextBinding({
   373	    bindingId: replacementBindingId,
   374	    stateRoot,
   375	    now: options.now,
   376	  });
   377	
   378	  return withBindingLock(stateRoot, bindingId, async () => {
   379	    const binding = await readBinding(stateRoot, bindingId);
   380	    if (!binding) {
   381	      throw new WorkContextError("WORK_CONTEXT_NOT_BOUND", `Work Context binding ${bindingId} does not exist`);
   382	    }
   383	    if (binding.status !== "active") {
   384	      throw new WorkContextError("WORK_CONTEXT_STALE", `Work Context binding ${bindingId} is already stale`);
   385	    }
   386	    if (binding.collaboration_space.key !== replacement.collaboration_space.key) {
