 92	const DEFAULT_MAX_AGE_MS = 24 * 60 * 60 * 1_000;
 93	const LOCK_TIMEOUT_MS = 5_000;
 94	const LOCK_RETRY_DELAY_MS = 20;
 95	const IDENTIFIER_PATTERN = /^[A-Za-z0-9._:-]+$/;
 96	const BINDING_ID_PATTERN = /^wctx_[a-f0-9]{32}$/;
 97	
 98	function nowIso(): string {
 99	  return new Date().toISOString();
100	}
101	
102	function requireIdentifier(value: string, name: string): string {
103	  if (!value || !IDENTIFIER_PATTERN.test(value)) {
104	    throw new WorkContextError(
105	      "WORK_CONTEXT_MISMATCH",
106	      `${name} must contain only letters, numbers, dots, underscores, colons, or hyphens`,
107	    );
108	  }
109	  return value;
110	}
111	
112	function requireBindingId(value: string): string {
113	  if (!BINDING_ID_PATTERN.test(value)) {
114	    throw new WorkContextError("WORK_CONTEXT_NOT_BOUND", `Work Context binding ${value || "<empty>"} is not valid`);
115	  }
116	  return value;
117	}
118	
119	export function resolveWorkContextStateRoot(stateRoot?: string): string {
120	  return resolve(stateRoot ?? process.env.ANVIL_STATE_ROOT ?? join(homedir(), ".anvil", "state"));
121	}
122	
123	export function bindingIdForSession(host: string, sessionId: string): string {
124	  const safeHost = requireIdentifier(host, "host");
125	  const safeSessionId = requireIdentifier(sessionId, "sessionId");
126	  const digest = createHash("sha256").update(`${safeHost}\0${safeSessionId}`).digest("hex").slice(0, 32);
127	  return `wctx_${digest}`;
128	}
