130	export function workContextBindingView(binding: WorkContextBinding): WorkContextBindingView {
131	  const { session_id: _sessionId, provenance, ...publicBinding } = binding;
132	  return {
133	    ...publicBinding,
134	    provenance: {
135	      kind: provenance.kind,
136	      lifecycle: provenance.lifecycle,
137	    },
138	  };
139	}
