141	export function assertActiveWorkContextBinding(binding: WorkContextBinding, now: Clock = nowIso): WorkContextBinding {
142	  if (
143	    !isWorkContextBinding(binding) ||
144	    !BINDING_ID_PATTERN.test(binding.id) ||
145	    binding.collaboration_space.key !== workspaceKeyForRoot(binding.collaboration_space.root)
146	  ) {
147	    throw new WorkContextError("WORK_CONTEXT_MISMATCH", "Work Context binding is malformed or internally inconsistent");
148	  }
149	  const observedAt = Date.parse(now());
150	  const expiration = Date.parse(binding.expires_at);
151	  if (
152	    binding.status !== "active" ||
153	    !Number.isFinite(observedAt) ||
154	    !Number.isFinite(expiration) ||
155	    observedAt > expiration
156	  ) {
157	    throw new WorkContextError("WORK_CONTEXT_STALE", `Work Context binding ${binding.id} is stale`);
158	  }
159	  return binding;
160	}
161	
162	function bindingPath(stateRoot: string, bindingId: string): string {
163	  return join(resolveWorkContextStateRoot(stateRoot), "work-context", "bindings", `${bindingId}.json`);
164	}
165	
166	function bindingLockPath(stateRoot: string, bindingId: string): string {
167	  return join(resolveWorkContextStateRoot(stateRoot), "work-context", "locks", `${bindingId}.lock`);
168	}
169	
170	function isNodeError(error: unknown): error is NodeJS.ErrnoException {
171	  return typeof error === "object" && error !== null && "code" in error;
172	}
173	
174	async function readBinding(stateRoot: string, bindingId: string): Promise<WorkContextBinding | undefined> {
175	  const path = bindingPath(stateRoot, bindingId);
176	  let text: string;
177	  try {
178	    text = await readFile(path, "utf8");
179	  } catch (error) {
180	    if (isNodeError(error) && error.code === "ENOENT") return undefined;
180	    if (isNodeError(error) && error.code === "ENOENT") return undefined;
181	    throw error;
182	  }
183	
184	  try {
185	    const parsed: unknown = JSON.parse(text);
186	    if (!isWorkContextBinding(parsed) || parsed.id !== bindingId) {
187	      throw new Error("stored binding does not match the Work Context schema");
188	    }
189	    return parsed;
190	  } catch (error) {
191	    throw new WorkContextError(
192	      "WORK_CONTEXT_MISMATCH",
193	      `Stored Work Context binding ${bindingId} is malformed`,
194	      { cause: error },
195	    );
196	  }
197	}
