199	export async function readStoredWorkContextBinding(
200	  options: Pick<RequireWorkContextBindingOptions, "bindingId" | "stateRoot">,
201	): Promise<WorkContextBinding | undefined> {
202	  const bindingId = requireBindingId(options.bindingId);
203	  return readBinding(resolveWorkContextStateRoot(options.stateRoot), bindingId);
204	}
205	
206	function isWorkspaceRef(value: unknown): value is WorkspaceRef {
207	  if (typeof value !== "object" || value === null) return false;
208	  const candidate = value as Partial<WorkspaceRef>;
209	  return (
210	    typeof candidate.key === "string" &&
211	    (candidate.kind === "git" || candidate.kind === "directory") &&
212	    typeof candidate.root === "string" &&
213	    (candidate.label === undefined || typeof candidate.label === "string")
214	  );
215	}
216	
217	function isWorkContextBinding(value: unknown): value is WorkContextBinding {
218	  if (typeof value !== "object" || value === null) return false;
219	  const candidate = value as Partial<WorkContextBinding>;
220	  const provenance = candidate.provenance;
221	  return (
222	    candidate.version === 1 &&
223	    typeof candidate.id === "string" &&
224	    (candidate.status === "active" || candidate.status === "superseded") &&
225	    typeof candidate.host === "string" &&
226	    typeof candidate.session_id === "string" &&
227	    typeof candidate.bound_at === "string" &&
228	    typeof candidate.last_seen_at === "string" &&
229	    typeof candidate.expires_at === "string" &&
230	    isWorkspaceRef(candidate.collaboration_space) &&
231	    typeof provenance === "object" &&
232	    provenance !== null &&
233	    (provenance.kind === "host_lifecycle" || provenance.kind === "operator_rebind") &&
234	    typeof provenance.lifecycle === "string" &&
235	    typeof provenance.observed_cwd === "string" &&
236	    (candidate.superseded_by === undefined || typeof candidate.superseded_by === "string") &&
237	    (candidate.superseded_at === undefined || typeof candidate.superseded_at === "string")
238	  );
239	}
