241	async function writeBindingAtomic(stateRoot: string, binding: WorkContextBinding): Promise<void> {
242	  const path = bindingPath(stateRoot, binding.id);
243	  await mkdir(dirname(path), { recursive: true, mode: 0o700 });
244	  const temporaryPath = `${path}.${process.pid}.${randomUUID()}.tmp`;
245	  await writeFile(temporaryPath, `${JSON.stringify(binding, null, 2)}\n`, { encoding: "utf8", mode: 0o600 });
246	  await rename(temporaryPath, path);
247	}
248	
249	async function withBindingLock<T>(stateRoot: string, bindingId: string, mutation: () => Promise<T>): Promise<T> {
250	  const lockPath = bindingLockPath(stateRoot, bindingId);
251	  const deadline = Date.now() + LOCK_TIMEOUT_MS;
252	  await mkdir(dirname(lockPath), { recursive: true, mode: 0o700 });
253	
254	  while (true) {
255	    try {
256	      await mkdir(lockPath, { mode: 0o700 });
257	      break;
258	    } catch (error) {
259	      if (!isNodeError(error) || error.code !== "EEXIST") throw error;
260	      if (Date.now() >= deadline) {
261	        throw new WorkContextError(
262	          "WORK_CONTEXT_AMBIGUOUS",
263	          `Timed out acquiring the lock for Work Context binding ${bindingId}`,
264	        );
265	      }
266	      await sleep(LOCK_RETRY_DELAY_MS);
267	    }
268	  }
269	
270	  try {
271	    return await mutation();
272	  } finally {
273	    await rm(lockPath, { recursive: true, force: true });
274	  }
275	}
276	
277	function expiresAt(observedAt: string, maxAgeMs: number): string {
278	  const timestamp = Date.parse(observedAt);
279	  if (!Number.isFinite(timestamp)) {
280	    throw new WorkContextError("WORK_CONTEXT_MISMATCH", `Clock returned an invalid timestamp: ${observedAt}`);
281	  }
282	  if (!Number.isFinite(maxAgeMs) || maxAgeMs <= 0) {
283	    throw new WorkContextError("WORK_CONTEXT_MISMATCH", "maxAgeMs must be a positive number");
284	  }
285	  return new Date(timestamp + maxAgeMs).toISOString();
286	}
