288	export async function bindWorkContext(
289	  options: BindWorkContextOptions,
290	): Promise<{ binding: WorkContextBinding; created: boolean }> {
291	  const bindingId = bindingIdForSession(options.host, options.sessionId);
292	  const lifecycle = requireIdentifier(options.lifecycle, "lifecycle");
293	  const stateRoot = resolveWorkContextStateRoot(options.stateRoot);
294	  const collaborationSpace = resolveCollaborationSpace(options.cwd);
295	  const observedCwd = realpathSync(resolve(options.cwd));
296	  const observedAt = (options.now ?? nowIso)();
297	  const expiration = expiresAt(observedAt, options.maxAgeMs ?? DEFAULT_MAX_AGE_MS);
298	
299	  return withBindingLock(stateRoot, bindingId, async () => {
300	    const existing = await readBinding(stateRoot, bindingId);
301	    if (existing) {
302	      if (
303	        existing.status !== "active" ||
304	        existing.host !== options.host ||
305	        existing.session_id !== options.sessionId ||
306	        existing.collaboration_space.key !== collaborationSpace.key
307	      ) {
308	        throw new WorkContextError(
309	          "WORK_CONTEXT_MISMATCH",
310	          `Session ${options.host}/${options.sessionId} is already bound to a different collaboration space or lifecycle`,
311	        );
312	      }
313	
314	      const binding: WorkContextBinding = {
315	        ...existing,
316	        last_seen_at: observedAt,
317	        expires_at: expiration,
318	        provenance: {
319	          kind: options.provenanceKind ?? "host_lifecycle",
320	          lifecycle,
321	          observed_cwd: observedCwd,
322	        },
323	      };
324	      await writeBindingAtomic(stateRoot, binding);
325	      return { binding, created: false };
326	    }
327	
328	    const binding: WorkContextBinding = {
329	      version: 1,
330	      id: bindingId,
331	      status: "active",
332	      host: options.host,
333	      session_id: options.sessionId,
334	      bound_at: observedAt,
335	      last_seen_at: observedAt,
336	      expires_at: expiration,
337	      collaboration_space: collaborationSpace,
338	      provenance: {
339	        kind: options.provenanceKind ?? "host_lifecycle",
340	        lifecycle,
341	        observed_cwd: observedCwd,
342	      },
343	    };
344	    await writeBindingAtomic(stateRoot, binding);
345	    return { binding, created: true };
346	  });
347	}
