349	export async function requireWorkContextBinding(
350	  options: RequireWorkContextBindingOptions,
351	): Promise<WorkContextBinding> {
352	  const bindingId = requireBindingId(options.bindingId);
353	  const stateRoot = resolveWorkContextStateRoot(options.stateRoot);
354	  const binding = await readStoredWorkContextBinding({ bindingId, stateRoot });
355	  if (!binding) {
356	    throw new WorkContextError("WORK_CONTEXT_NOT_BOUND", `Work Context binding ${bindingId} does not exist`);
357	  }
358	
359	  return assertActiveWorkContextBinding(binding, options.now);
360	}
